<div class="stack" x-cloak x-show="!loading && !loadError"><div class="stats-strip !mb-0"><div class="stat"><p class="stat-label">Rata-rata periode</p><p class="stat-value num" x-text="$number(data.average)"></p><small>Hanya penilaian Final</small></div><div class="stat"><p class="stat-label">Jumlah penilaian Final</p><p class="stat-value num" x-text="data.final_count || 0"></p><small x-text="ui.month(ui.cycle?.assessment_month)"></small></div><div class="stat"><p class="stat-label">Kelompok sebanding</p><p class="stat-value num" x-text="data.groups.length"></p><small>Jabatan, template, dan jenis sama</small></div><div class="stat"><p class="stat-label">Cakupan</p><p class="mt-3 font-semibold" x-text="ui.scope"></p><small x-text="ui.roleLabel"></small></div></div><x-trend data="data.trend"/><div class="columns"><div class="panel panel-pad"><h2 class="panel-title mb-4">Rata-rata per kelompok sebanding</h2><div class="table-wrap"><table class="table"><thead><tr><th>Jabatan / template</th><th>Jenis</th><th class="numeric">Jumlah</th><th class="numeric">Rata-rata</th></tr></thead><tbody><template x-for="group in data.groups" :key="group.kpi_template_id+'-'+group.assessment_kind"><tr><td><strong x-text="group.position_name"></strong><span class="subtext" x-text="group.template_name"></span></td><td x-text="group.assessment_kind==='unit_head'?'Kepala Unit':'Anggota'"></td><td class="numeric" x-text="group.count"></td><td class="numeric" x-text="$number(group.average)"></td></tr></template><tr x-show="!data.groups.length"><td colspan="4" class="muted">Belum ada kelompok nilai Final.</td></tr></tbody></table></div></div><div class="panel panel-pad"><h2 class="panel-title mb-4">Sebaran kategori</h2><template x-for="category in data.categories" :key="category.code"><div class="mb-4"><div class="flex justify-between gap-4"><span x-text="category.label"></span><strong class="num" x-text="category.count"></strong></div><div class="progress"><span :style="'width:'+(data.final_count?category.count/data.final_count*100:0)+'%'"></span></div></div></template><p class="muted small" x-show="!data.categories.length">Belum ada kategori hasil Final.</p></div></div><div class="panel panel-pad"><h2 class="panel-title mb-4">Matriks riwayat karyawan</h2><p class="muted small mb-4">Klik nilai untuk membaca lembar Final. Histori yang tidak termasuk kewenangan akun tidak ditampilkan.</p><div class="table-wrap"><table class="table"><thead><tr><th>Karyawan</th><template x-for="point in data.trend" :key="point.month"><th class="numeric" x-text="$shortMonth(point.month)"></th></template></tr></thead><tbody><template x-for="person in matrix" :key="person.id"><tr><td><strong x-text="person.name"></strong><span class="subtext" x-text="person.unit"></span></td><template x-for="point in data.trend" :key="point.month"><td class="numeric"><template x-if="person.values[point.month]"><a class="brand underline underline-offset-4" :href="ui.link('assessments/'+person.values[point.month].id)" x-text="$number(person.values[point.month].total_score_raw)"></a></template><span x-show="!person.values[point.month]">Tidak ada</span></td></template></tr></template><tr x-show="!matrix.length"><td colspan="13" class="muted">Belum ada riwayat Final pada rentang ini.</td></tr></tbody></table></div></div></div></section>
